  };
  const originalLog = console.log;
  const originalWarn = console.warn;
  console.log = (...args) => {
    if (shouldSuppressPdfWarning(args)) return;
    originalLog(...args);
  };
  console.warn = (...args) => {
    if (shouldSuppressPdfWarning(args)) return;
    originalWarn(...args);
  };
  try {
    return await import("../../src/background/tools/runtime.js");
  } finally {
    console.log = originalLog;
    console.warn = originalWarn;
  }
